@startuml

class SensorController {
  + systemName : string
  + querySensorValues(sensorId : string) : float
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalConsumption : float
}

class Inhabitant {
  + username : string
  + password : string
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {
  + checkThresholds() : void
  + sendAlert(email : string) : void
}

enum Unit {
  CELSIUS
  WATT
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Inhabitant "1..*" -- "1" Apartment
Inhabitant "0..1" -- "1" SensorController : admin
Sensor "1" -- "1..*" MeasuredValue
Sensor "1" -- "0..1" MeasuredValue : lastValue
Sensor "1" -- "0..1" float : threshold
SensorController "1" -- "1" EMonitor
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

